\set ON_ERROR_STOP on
begin;
create schema auth;
do $$ begin if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated; end if; if not exists(select 1 from pg_roles where rolname='anon') then create role anon; end if; if not exists(select 1 from pg_roles where rolname='service_role') then create role service_role; end if; end $$;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('test.uid',true),'')::uuid $$;
create function pg_temp.id(n int) returns uuid language sql immutable as $$ select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid $$;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAIL: %',label; end if; end $$;
create type public.listing_status as enum('draft','inactive','active','suspended');
create type public.availability_status as enum('available');
create table marketplace_settings(id boolean primary key,agent_listing_payments_enabled boolean);
insert into marketplace_settings values(true,true);
create function agent_listing_payments_enabled() returns boolean language sql stable as $$ select agent_listing_payments_enabled from marketplace_settings where id=true $$;
create table agents(id uuid primary key,profile_id uuid,verification_status text,account_status text);
create table agent_subscription_plans(id text primary key,publication_fee_tzs integer);
create table agent_subscriptions(agent_id uuid,plan_id text,status text,expires_at timestamptz);
create table listings(id uuid primary key,agent_id uuid,status listing_status,publication_requested boolean default false,removed_from_market_at timestamptz,removed_reason text,published_at timestamptz,publication_review_status text default 'auto_approved',has_media boolean default true);
create table agent_listing_payments(listing_id uuid,agent_id uuid,payment_status text);
create function listing_has_publishable_media(p_listing_id uuid) returns boolean language sql stable as $$ select has_media from listings where id=p_listing_id $$;
create function admin_set_listing_marketplace_status(uuid,listing_status,availability_status,text,text) returns jsonb language plpgsql as $$
declare v_listing public.listings%rowtype; v_payment_required boolean;
begin
 select * into v_listing from listings where id=$1;
 v_payment_required := public.agent_listing_payments_enabled();
 return jsonb_build_object('paymentRequired',v_payment_required);
end $$;
